const input = $json ?? {};
const deal = input.deal ?? input.transaction ?? input;
const update = input.milestone_update ?? input.milestone ?? {};
const status = String(update.status ?? '').toLowerCase();
const dueDate = update.due_date ? new Date(update.due_date) : null;
const now = new Date();
const overdue = Boolean(dueDate && !Number.isNaN(dueDate.getTime()) &&
  dueDate.getTime() < now.getTime() &&
  !['completed','complete','closed','cancelled','waived'].includes(status));

const exceptionTypes = [];
if (overdue) exceptionTypes.push('overdue_milestone');
if (['failed','blocked','rejected','cancelled','terminated'].includes(status)) exceptionTypes.push('milestone_failure');
if (update.blocker) exceptionTypes.push('blocker');
if (update.missing_evidence) exceptionTypes.push('missing_evidence');
if (update.critical_date_at_risk) exceptionTypes.push('critical_date_at_risk');

const blockers = Array.isArray(deal.blockers) ? deal.blockers.filter(Boolean) : [];
const identityComplete = Boolean(deal.deal_id ?? deal.transaction_id) &&
  Boolean(deal.property_id) &&
  Boolean(deal.lead_id ?? deal.seller_id);
const executionState = String(deal.execution_state ?? deal.agreement?.execution_state ?? '').toLowerCase();
const signedEvidence = Boolean(deal.signed_evidence ?? deal.agreement?.signed_evidence);

let severity = 'normal';
let disposition = 'record_only';
if (!identityComplete || executionState !== 'executed' || !signedEvidence) {
  severity = 'urgent';
  disposition = 'human_review';
} else if (exceptionTypes.includes('milestone_failure') || exceptionTypes.includes('critical_date_at_risk')) {
  severity = 'urgent';
  disposition = 'escalate';
} else if (exceptionTypes.length || blockers.length) {
  severity = 'high';
  disposition = 'attention_required';
}

const routing = disposition === 'human_review' || disposition === 'escalate'
  ? {next_workflow:'WF-126',reason:'Closing exception requires escalation/coordination.'}
  : exceptionTypes.length || blockers.length
    ? {next_workflow:'WF-155',reason:'Milestone exception requires closing orchestration and follow-up.'}
    : {next_workflow:'WF-136',reason:'Milestone update is recorded; continue critical-date monitoring.'};

return [{
  json:{
    ...input,
    workflow_id:'WF-173',
    workflow_name:'Closing Milestone Update → Exception & Escalation Controller',
    milestone_update:{
      id:update.id ?? null,
      name:update.name ?? null,
      status:update.status ?? null,
      due_date:update.due_date ?? null,
      overdue,
      exception_types:exceptionTypes
    },
    identity_complete:identityComplete,
    execution_state:executionState,
    signed_evidence_present:signedEvidence,
    blockers,
    decision:{severity,disposition},
    routing
  }
}];

const out = $json ?? {};
return [{
  json:{
    ...out,
    workflow_id:'WF-173',
    result:'closing_milestone_exception_evaluated',
    next_workflow:out.routing?.next_workflow ?? 'WF-136'
  }
}];
